(7303738, 1139052, 179675, '<td valign="top">Fantastic! Really loving the rusty finish on the bike. Thinking this would''ve rocked if it was a long-exposure!</td>', 'Fantastic! Really loving the rusty finish on the bike. Thinking this would''ve rocked if it was a long-exposure!', '2015-01-18 12:51:34.000000', NULL, 1),
