(7304646, 1138949, 114225, '<td valign="top">Wow. This is an instant fav.</td>', 'Wow. This is an instant fav.', '2015-01-20 19:10:56.000000', NULL, 1),
(7304655, 1139124, 176839, '<td valign="top">Hi I don''t comment much, but wanted to on this one. love the portrait. would have preferred if you had shot this face-on,  rather that from lower down. as the hands distract from that beautiful face. also would have loved it if you would have cropped it a bit to the left so the subject was not in the middle. would have added more interest.(imho) beautiful light and shade. well done. hope this does well.</td>', 'Hi I don''t comment much, but wanted to on this one. love the portrait. would have preferred if you had shot this face-on,  rather that from lower down. as the hands distract from that beautiful face. also would have loved it if you would have cropped it a bit to the left so the subject was not in the middle. would have added more interest.(imho) beautiful light and shade. well done. hope this does well.', '2015-01-20 19:43:25.000000', NULL, 1),
(7304664, 1138395, 150277, '<td valign="top">Very cool.</td>', 'Very cool.', '2015-01-20 20:26:52.000000', NULL, 1),
(7304672, 1138468, 135629, '<td valign="top">Fantastic image, very calming colors, sharp subject, and very nice DOF. 10</td>', 'Fantastic image, very calming colors, sharp subject, and very nice DOF. 10', '2015-01-20 20:41:57.000000', NULL, 1),
(7304674, 1138887, 150277, '<td valign="top">I love the black against the yellow leaf, wonderful color. Beautiful macro.</td>', 'I love the black against the yellow leaf, wonderful color. Beautiful macro.', '2015-01-20 20:55:21.000000', NULL, 1),
(7304724, 1138387, 30982, '<td valign="top">I suspect our favorite French photographer here.  Excellent combination of patience, luck, a great eye, and some nice processing as well.  One of the best of the bunch.</td>', 'I suspect our favorite French photographer here.  Excellent combination of patience, luck, a great eye, and some nice processing as well.  One of the best of the bunch.', '2015-01-20 22:23:06.000000', NULL, 1),
(7304725, 1138596, 30982, '<td valign="top">One of my favorites of the challenge.  The mini seems oddly out of place, but fits there nicely just the same.  Really like the high contrast, too.  Great shot.</td>', 'One of my favorites of the challenge.  The mini seems oddly out of place, but fits there nicely just the same.  Really like the high contrast, too.  Great shot.', '2015-01-20 22:24:00.000000', NULL, 1),
(7304726, 1138371, 30982, '<td valign="top">Gotta love it.  Wonderful corner, great car to park there.</td>', 'Gotta love it.  Wonderful corner, great car to park there.', '2015-01-20 22:24:19.000000', NULL, 1),
(7304727, 1139348, 30982, '<td valign="top">This just touches my heart, even without the sappy title.</td>', 'This just touches my heart, even without the sappy title.', '2015-01-20 22:24:49.000000', NULL, 1),
