(7304752, 1139238, 30490, '<td valign="top">Big kitty!  Don''t want to be staring down that face!  Great lighting and expression on the cat''s face</td>', 'Big kitty!  Don''t want to be staring down that face!  Great lighting and expression on the cat''s face', '2015-01-20 22:58:07.000000', NULL, 1),
(7304755, 1139290, 30490, '<td valign="top">I loved this when it was in a challenge and I still love it in the Best of 2014.  It is so busy. but so very interesting and the contrast with the man buffing the floor just really works in the overall composition.</td>', 'I loved this when it was in a challenge and I still love it in the Best of 2014.  It is so busy. but so very interesting and the contrast with the man buffing the floor just really works in the overall composition.', '2015-01-20 22:59:26.000000', NULL, 1),
(7304756, 1139446, 30490, '<td valign="top">Love the texture and the contrast with the magma hole.  Nice capture!</td>', 'Love the texture and the contrast with the magma hole.  Nice capture!', '2015-01-20 23:00:00.000000', NULL, 1),
(7304757, 1139595, 30490, '<td valign="top">Amazing clarity on this image!  The colors are terrific too!</td>', 'Amazing clarity on this image!  The colors are terrific too!', '2015-01-20 23:00:22.000000', NULL, 1),
