(7304764, 1139586, 30490, '<td valign="top">Terrific clarity and detail in this image.  Love the colors of the background and the eyes too.</td>', 'Terrific clarity and detail in this image.  Love the colors of the background and the eyes too.', '2015-01-20 23:05:15.000000', NULL, 1),
(7304767, 1139447, 30490, '<td valign="top">Interesting texture, great reflection, sun set rays, interesting clouds - this image has it all!</td>', 'Interesting texture, great reflection, sun set rays, interesting clouds - this image has it all!', '2015-01-20 23:07:06.000000', NULL, 1),
