(7305168, 1139448, 13077, '<td valign="top">She has some very nice interesting eyers. Composed well but it is a bit grainy, not really a big deal though.</td>', 'She has some very nice interesting eyers. Composed well but it is a bit grainy, not really a big deal though.', '2015-01-21 16:38:01.000000', NULL, 1),
(7305169, 1138416, 13077, '<td valign="top">Fantastic light you caught there. Looks like a very nice place.</td>', 'Fantastic light you caught there. Looks like a very nice place.', '2015-01-21 16:38:24.000000', NULL, 1),
(7305170, 1139524, 13077, '<td valign="top">lol. nice title. I like the action you caught, and it''s composed well with pleasant color tones.</td>', 'lol. nice title. I like the action you caught, and it''s composed well with pleasant color tones.', '2015-01-21 16:38:48.000000', NULL, 1),
(7305171, 1139602, 13077, '<td valign="top">Well composed and positioned to get the stand of trees within the horizon of those mountains. Very well exposed too, looks polished overall but I might suggest cropping out the small rocks at the bottom center.</td>', 'Well composed and positioned to get the stand of trees within the horizon of those mountains. Very well exposed too, looks polished overall but I might suggest cropping out the small rocks at the bottom center.', '2015-01-21 16:39:59.000000', NULL, 1),
(7305173, 1138950, 13077, '<td valign="top">Nicely handled with the different lighting conditions, and exceptionally free from lens flare despite the harsh light and high-ISO to bring out the stars so well. I would be interested to read some notes of your techniques in the description.</td>', 'Nicely handled with the different lighting conditions, and exceptionally free from lens flare despite the harsh light and high-ISO to bring out the stars so well. I would be interested to read some notes of your techniques in the description.', '2015-01-21 16:41:35.000000', NULL, 1),
(7305174, 1139178, 13077, '<td valign="top">Very bright and bold, well captured action and pleasing background with the gentle waves. Nicely done.</td>', 'Very bright and bold, well captured action and pleasing background with the gentle waves. Nicely done.', '2015-01-21 16:42:28.000000', NULL, 1),
(7305175, 1138616, 13077, '<td valign="top">Great job with the falling snow and the color tones. A top-notch candid shot for sure.</td>', 'Great job with the falling snow and the color tones. A top-notch candid shot for sure.', '2015-01-21 16:42:56.000000', NULL, 1),
(7305177, 1138408, 13077, '<td valign="top">I like the edge-heavy composition. It feels tense but balanced. Grain looks good too, suits the environment well.</td>', 'I like the edge-heavy composition. It feels tense but balanced. Grain looks good too, suits the environment well.', '2015-01-21 16:43:47.000000', NULL, 1),
(7305179, 1139512, 13077, '<td valign="top">I like the way the scene has created sort of a natural panoramic photo for you.</td>', 'I like the way the scene has created sort of a natural panoramic photo for you.', '2015-01-21 16:47:16.000000', NULL, 1),
(7305180, 1139496, 13077, '<td valign="top">An attractive scene, super interesting clouds. Well processed too.</td>', 'An attractive scene, super interesting clouds. Well processed too.', '2015-01-21 16:48:01.000000', NULL, 1),
(7305182, 1138433, 13077, '<td valign="top">Super cool environment you captured here. Great light and the steam rising is very interesting.</td>', 'Super cool environment you captured here. Great light and the steam rising is very interesting.', '2015-01-21 16:56:09.000000', NULL, 1),
(7305183, 1139088, 13077, '<td valign="top">Looks like an alien landscape. Very cool.</td>', 'Looks like an alien landscape. Very cool.', '2015-01-21 16:56:30.000000', NULL, 1),
(7305186, 1139351, 76335, '<td valign="top">They put on a good show...</td>', 'They put on a good show...', '2015-01-21 17:19:21.000000', NULL, 1),
(7305187, 1138962, 13077, '<td valign="top">Good one - nice action and composition, and good bright greens.</td>', 'Good one - nice action and composition, and good bright greens.', '2015-01-21 17:19:26.000000', NULL, 1),
