INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7307657, 1138463, 3548, '<td valign="top"><br/>Trés bien fait, monsieur.<br/>Tous les deux!</td>', 'Trés bien fait, monsieur.Tous les deux!', '2015-01-28 15:39:57.000000', NULL, 0),
(7310249, 1139476, 69668, '<td valign="top">This is lovely!</td>', 'This is lovely!', '2015-02-03 20:18:28.000000', NULL, 0),
(7323829, 1139006, 113016, '<td valign="top">this is outstanding.  nice work!</td>', 'this is outstanding.  nice work!', '2015-03-05 16:27:14.000000', NULL, 0),
(7354461, 1138735, 150277, '<td valign="top">Awww, I think this is really special.  I was one of your 6''s.  The only shots of people that I scored higher had really dramatic lighting or really unique scenery.  (While I get this was a honest shot taken during an actual birthday event, I can''t help but wonder if the DPC peeps might have scored it higher had this been a setup shot on a scene with a clean (white?) background.  <br/> <br/>Frankly I think this image is more special the way it is.  I hope you have this beauty framed to enjoy. (I guess maybe the average score doesn''t reflect this as above just a snapshot, but to me there is a huge difference between a snapshot and what you captured.)<br/><br/><i>Message edited by author 2015-05-27 23:12:18.</i></td>', 'Awww, I think this is really special.  I was one of your 6''s.  The only shots of people that I scored higher had really dramatic lighting or really unique scenery.  (While I get this was a honest shot taken during an actual birthday event, I can''t help but wonder if the DPC peeps might have scored it higher had this been a setup shot on a scene with a clean (white?) background.   Frankly I think this image is more special the way it is.  I hope you have this beauty framed to enjoy. (I guess maybe the average score doesn''t reflect this as above just a snapshot, but to me there is a huge difference between a snapshot and what you captured.)', '2015-05-28 00:07:51.000000', '2015-05-28 00:12:18.000000', 0),
(7354480, 1138735, 30982, '<td valign="top">That look is priceless!  This is the kind of shot I enjoy - a real moment in time, suspended in pixels (used to be on film, but hey....)  The only thing I might suggest is brightening it up a bit and toning down the yellow from the interior lighting.</td>', 'That look is priceless!  This is the kind of shot I enjoy - a real moment in time, suspended in pixels (used to be on film, but hey....)  The only thing I might suggest is brightening it up a bit and toning down the yellow from the interior lighting.', '2015-05-28 01:01:09.000000', NULL, 0),
(7354483, 1138735, 138630, '<td valign="top">Yes, I just noticed the yellow on my laptop - have always viewed the image at home and never noticed that.  She is not yellow - could also be from candle light.  Anyway, thanks for the comments and suggestions, you two.  I appreciate them.</td>', 'Yes, I just noticed the yellow on my laptop - have always viewed the image at home and never noticed that.  She is not yellow - could also be from candle light.  Anyway, thanks for the comments and suggestions, you two.  I appreciate them.', '2015-05-28 01:13:14.000000', NULL, 0),
(7354561, 1138735, 63398, '<td valign="top">It''s positively lovely. PLEASE enlarge, matte, &amp; frame it for Mom &amp; Dad. This is something they will cherish forever.</td>', 'It''s positively lovely. PLEASE enlarge, matte, & frame it for Mom & Dad. This is something they will cherish forever.', '2015-05-28 09:39:29.000000', NULL, 0),
(7354594, 1138735, 138630, '<td valign="top">Thanks, Jeb.  As I said, family (me included) love it.  The DPC score made me indignant but did not diminish its personal appeal :)</td>', 'Thanks, Jeb.  As I said, family (me included) love it.  The DPC score made me indignant but did not diminish its personal appeal :)', '2015-05-28 11:05:13.000000', NULL, 0),
(7398196, 1139306, 25024, '<td valign="top">*Hello from Sid and the Critique Club*<br/> <br/>A futuristic looking image that is assumed to meet the challenge<br/> <br/>Your image has a very futuristic feel to and as has been observed amongst your commenters very clean lines that to me make it look like an architects proposed plans for a bridge project. That is not meant to be a negative remark but one that recognises the sharpness and DOF throughout. The red tones of the bridge make it stand out strongly against the cold blues of the rest of the image.<br/> <br/>The composition is very good emphasising the unique bridge against the cityscape, the frozen river and the plain blue sky this all hangs together very well indeed. Looking carefully at the sky I am feeling that there may be some banding there but its very feint and  unobtrusive.<br/> <br/>All in all, an excellent submission that must have had some tough competition to place so low with such a respectable score. Thanks, Sid</td>', '*Hello from Sid and the Critique Club* A futuristic looking image that is assumed to meet the challenge Your image has a very futuristic feel to and as has been observed amongst your commenters very clean lines that to me make it look like an architects proposed plans for a bridge project. That is not meant to be a negative remark but one that recognises the sharpness and DOF throughout. The red tones of the bridge make it stand out strongly against the cold blues of the rest of the image. The composition is very good emphasising the unique bridge against the cityscape, the frozen river and the plain blue sky this all hangs together very well indeed. Looking carefully at the sky I am feeling that there may be some banding there but its very feint and  unobtrusive. All in all, an excellent submission that must have had some tough competition to place so low with such a respectable score. Thanks, Sid', '2015-08-18 11:49:42.000000', NULL, 0),
(7398201, 1138265, 25024, '<td valign="top">*Hello from Sid and the Critique Club*<br/> <br/>An excellent portrait that is assumed to fulfil the challenge.<br/> <br/>A very striking portrait that, like all good photography, is all about the light. I like your low viewpoint which has allowed you to exclude potential distractions and isolate your subject against a plainer background. Your portrait is also about timing, you have captured a reflective moment that works well because it suggests a natural expression that shows a complete unawareness of the camera or anything else at that moment in time.<br/> <br/>Your exposure is generally good with good detail throughout though I do feel that you are pushing close to the boundaries of overexposure in some rather important areas mainly the lady''s forehead. If you had underexposed by a third of a stop I think you would have given just a bit more room without darkening her face too much though it is, I have to admit, I very fine line. There is possibly a little too much space above her head but her gaze needs some space to look into and because of it I think you just about get away with it.<br/> <br/>It is a very appealing portrait that in any other related challenge would have done well but the nature of this particular challenge is lots of high quality entries to compete against. Well done, Sid</td>', '*Hello from Sid and the Critique Club* An excellent portrait that is assumed to fulfil the challenge. A very striking portrait that, like all good photography, is all about the light. I like your low viewpoint which has allowed you to exclude potential distractions and isolate your subject against a plainer background. Your portrait is also about timing, you have captured a reflective moment that works well because it suggests a natural expression that shows a complete unawareness of the camera or anything else at that moment in time. Your exposure is generally good with good detail throughout though I do feel that you are pushing close to the boundaries of overexposure in some rather important areas mainly the lady''s forehead. If you had underexposed by a third of a stop I think you would have given just a bit more room without darkening her face too much though it is, I have to admit, I very fine line. There is possibly a little too much space above her head but her gaze needs some space to look into and because of it I think you just about get away with it. It is a very appealing portrait that in any other related challenge would have done well but the nature of this particular challenge is lots of high quality entries to compete against. Well done, Sid', '2015-08-18 12:03:08.000000', NULL, 0),
(7398487, 1138378, 25024, '<td valign="top">*Hello from Sid and the Critique Club*<br/> <br/>An excellent figure study assumed to meet the challenge.<br/> <br/>This is a very capable study worthy of all the aching limbs and effort involved! I like your composition and her pose, the windy evening gives it another dynamic, the exposure is good through most of the image. I also like the shape and colours in the shawl she is holding and the way it is blown by the wind.<br/> <br/>There are two issues that needed a bit more attention to detail, one is the slight cropping of the shawl, there is a lot of base that could easily have been sacrificed to get all of the shawl in frame. The other is the sloping sea!<br/> <br/>This is generally good submission that was up against the toughest competition, well done, Sid</td>', '*Hello from Sid and the Critique Club* An excellent figure study assumed to meet the challenge. This is a very capable study worthy of all the aching limbs and effort involved! I like your composition and her pose, the windy evening gives it another dynamic, the exposure is good through most of the image. I also like the shape and colours in the shawl she is holding and the way it is blown by the wind. There are two issues that needed a bit more attention to detail, one is the slight cropping of the shawl, there is a lot of base that could easily have been sacrificed to get all of the shawl in frame. The other is the sloping sea! This is generally good submission that was up against the toughest competition, well done, Sid', '2015-08-19 10:07:24.000000', NULL, 0),
(7398491, 1139214, 25024, '<td valign="top">*Hello from Sid and the Critique Club*<br/> <br/>A pleasing landscape that is assumed to meet the challenge<br/> <br/>A lovely location that has been enhanced by your thoughtful inclusion of your wife in the scene. Her inclusion gives us a good strong focal point and also gives us a sense of scale of the grandeur of the location. I like the skies a lot.<br/> <br/>Your composition and exposure are generally good, the reflections are a welcome addition. Technically your settings are good, nice low ISO and I assume a good tripod for support. You have achieved a huge DOF through your choice of a small aperture though if this actually the smallest aperture I would generally avoid it in the interests of best image quality.<br/> <br/>Like your commenter I am not keen on HDR treatment, the colours are a little too saturated for me, I prefer more subtlety and a more natural looking result though having said that your image is a lot better than many I have seen using this technique.<br/> <br/>Thanks for your submission, Sid</td>', '*Hello from Sid and the Critique Club* A pleasing landscape that is assumed to meet the challenge A lovely location that has been enhanced by your thoughtful inclusion of your wife in the scene. Her inclusion gives us a good strong focal point and also gives us a sense of scale of the grandeur of the location. I like the skies a lot. Your composition and exposure are generally good, the reflections are a welcome addition. Technically your settings are good, nice low ISO and I assume a good tripod for support. You have achieved a huge DOF through your choice of a small aperture though if this actually the smallest aperture I would generally avoid it in the interests of best image quality. Like your commenter I am not keen on HDR treatment, the colours are a little too saturated for me, I prefer more subtlety and a more natural looking result though having said that your image is a lot better than many I have seen using this technique. Thanks for your submission, Sid', '2015-08-19 10:21:28.000000', NULL, 0),
(7398518, 1139057, 25024, '<td valign="top">*Hello from Sid and the Critique Club*<br/> <br/>A landscape assumed to fulfil the challenge brief<br/> <br/>Given your description I would say you have achieved your goal with the chosen scene. There are, however, a few things I would like to talk about in order to help you try and improve upon your end result.<br/> <br/>First of all your image is smaller than it needs to be which would inevitably go against you with the voters here so always try and make the most of your image through the challenge dimensions allowed.<br/> <br/>Your image has all of the qualities you were seeking, isolation, solitude and loneliness being ways of expressing the same thing this location does seem to fulfil that objective. Decay is also represented with the roof of the building, and all of this against the purity of the snow which is unfortunately greyer than pure white snow needs to be. As your camera meter is always designed to give an average result for the average scene (18% grey) it will  inevitably underexpose the snow and need brightening up in post processing. The problem here is that you will need to select just the snow as you already have over-exposure in the sky so you cannot simply give more exposure throughout.<br/> <br/>Your composition could be improved, the building is very central, it would have a lot more impact of you had used the rule of thirds for placement of the building. The whole scene feels as if could benefit from more contrast it is a little lacking at the moment. There is vignetting which may be deliberate but I think it would be better without.<br/> <br/>Thank you for your submission, I hope my comments help, Sid</td>', '*Hello from Sid and the Critique Club* A landscape assumed to fulfil the challenge brief Given your description I would say you have achieved your goal with the chosen scene. There are, however, a few things I would like to talk about in order to help you try and improve upon your end result. First of all your image is smaller than it needs to be which would inevitably go against you with the voters here so always try and make the most of your image through the challenge dimensions allowed. Your image has all of the qualities you were seeking, isolation, solitude and loneliness being ways of expressing the same thing this location does seem to fulfil that objective. Decay is also represented with the roof of the building, and all of this against the purity of the snow which is unfortunately greyer than pure white snow needs to be. As your camera meter is always designed to give an average result for the average scene (18% grey) it will  inevitably underexpose the snow and need brightening up in post processing. The problem here is that you will need to select just the snow as you already have over-exposure in the sky so you cannot simply give more exposure throughout. Your composition could be improved, the building is very central, it would have a lot more impact of you had used the rule of thirds for placement of the building. The whole scene feels as if could benefit from more contrast it is a little lacking at the moment. There is vignetting which may be deliberate but I think it would be better without. Thank you for your submission, I hope my comments help, Sid', '2015-08-19 11:24:10.000000', NULL, 0),
(7398712, 1138872, 25024, '<td valign="top">*Hello from Sid and the Critique Club*<br/> <br/>A very competent image that is assumed to meet the challenge-w<br/> <br/>This is a very well executed image that has a lot of appeal. You have very effectively countered the biggest challenge you were faced with, that of reflections off the glass, by using the rubber hood you have completely overcome it and produced something of quality. An apt title sums up what I like about the image, the incandescent hues against the translucency with the black background all work together very effectively.<br/> <br/>Even though you are at presumably maximum aperture you have still got a good DOF here that captures all of the body detail well.  I like your commenters remarks and concur with them fully. I think because we are more used to seeing a jellyfish in a top down posture we are thrown by the angle here, not that it doesn''t work but perhaps a rotation may have secured an even better score.<br/> <br/>In an another appropriate challenge this would have placed very highly indeed but in this challenge you are up against a lot of high quality entries but you still did well, thanks for a great entry, Sid</td>', '*Hello from Sid and the Critique Club* A very competent image that is assumed to meet the challenge-w This is a very well executed image that has a lot of appeal. You have very effectively countered the biggest challenge you were faced with, that of reflections off the glass, by using the rubber hood you have completely overcome it and produced something of quality. An apt title sums up what I like about the image, the incandescent hues against the translucency with the black background all work together very effectively. Even though you are at presumably maximum aperture you have still got a good DOF here that captures all of the body detail well.  I like your commenters remarks and concur with them fully. I think because we are more used to seeing a jellyfish in a top down posture we are thrown by the angle here, not that it doesn''t work but perhaps a rotation may have secured an even better score. In an another appropriate challenge this would have placed very highly indeed but in this challenge you are up against a lot of high quality entries but you still did well, thanks for a great entry, Sid', '2015-08-20 10:58:25.000000', NULL, 0),
(7398715, 1139137, 25024, '<td valign="top">*Hello from Sid and the Critique Club*<br/> <br/>A very striking portrait that is assumed to meet the challenge<br/> <br/>A good and striking portrait such as you have captured here is all about the eyes, the confident eye contact that has that sparkle in it, and it''s here in abundance. I also like your diagonal composition as opposed to a normal straight on portrait it has created a much more dynamic feel to the image as a whole.<br/> <br/>I wish the background was more uniform without the bright area immediately next to his face, perhaps it might be an idea to dodge it a little just to reduce its impact. Other than that there is nothing further that I would alter about it.<br/> <br/>Thanks for a great submission in a very challenging challenge, Sid</td>', '*Hello from Sid and the Critique Club* A very striking portrait that is assumed to meet the challenge A good and striking portrait such as you have captured here is all about the eyes, the confident eye contact that has that sparkle in it, and it''s here in abundance. I also like your diagonal composition as opposed to a normal straight on portrait it has created a much more dynamic feel to the image as a whole. I wish the background was more uniform without the bright area immediately next to his face, perhaps it might be an idea to dodge it a little just to reduce its impact. Other than that there is nothing further that I would alter about it. Thanks for a great submission in a very challenging challenge, Sid', '2015-08-20 11:09:51.000000', NULL, 0),
(7398720, 1139446, 25024, '<td valign="top">*Hello from Sid and the Critique Club*<br/> <br/> A unique shot assumed to meet the challenge.<br/> <br/>There can''t be many of these shots made last year! A fascinating view of something that most of us never have and probably never will see in our lifetimes. The amazing patterns that the flow has cooled into are quite compelling. I like the splash of red of the hot magma against the drab grey of the rest of the image, I also like your placement of it on one of the thirds hotspots it works well.<br/> <br/>The only thing I would like to comment on is that the corners are a little soft. This is presumably your maximum aperture, if so, I think stopping down to f8 would have given you sharper detail throughout even at the same ISO setting.<br/> <br/>A very good and interesting submission which did well for you in probably the toughest challenge of the year, well done, Sid</td>', '*Hello from Sid and the Critique Club*  A unique shot assumed to meet the challenge. There can''t be many of these shots made last year! A fascinating view of something that most of us never have and probably never will see in our lifetimes. The amazing patterns that the flow has cooled into are quite compelling. I like the splash of red of the hot magma against the drab grey of the rest of the image, I also like your placement of it on one of the thirds hotspots it works well. The only thing I would like to comment on is that the corners are a little soft. This is presumably your maximum aperture, if so, I think stopping down to f8 would have given you sharper detail throughout even at the same ISO setting. A very good and interesting submission which did well for you in probably the toughest challenge of the year, well done, Sid', '2015-08-20 11:22:26.000000', NULL, 0),
(7398745, 1139067, 25024, '<td valign="top">*Hello from Sid and the Critique Club*<br/> <br/>An interesting shot assumed to meet the challenge.<br/> <br/>A great composition of an interesting location. Well done for looking for the puddle and reflection to add that extra interest to your image and placing it in one of the hotspots to complete your composition. The colours and patterns of the rocks are what make the image stand out and you have made these a major element of your image to good effect.<br/> <br/>For some inexplicable reason I have problems with the buildings, they feel like cutouts that have been added after, I know they haven''t but that''s how they feel, particularly the nearest red building. It''s a shame because it is an appealing image but the feeling is so strong it is detracting from my overall appreciation of it. I can only assume its down to the processing, it feels as though its somehow lost its natural look.<br/> <br/>I''m pleased for you that most people here appreciated and enjoyed it, scoring well in a highly contested challenge, well done Janine, Sid</td>', '*Hello from Sid and the Critique Club* An interesting shot assumed to meet the challenge. A great composition of an interesting location. Well done for looking for the puddle and reflection to add that extra interest to your image and placing it in one of the hotspots to complete your composition. The colours and patterns of the rocks are what make the image stand out and you have made these a major element of your image to good effect. For some inexplicable reason I have problems with the buildings, they feel like cutouts that have been added after, I know they haven''t but that''s how they feel, particularly the nearest red building. It''s a shame because it is an appealing image but the feeling is so strong it is detracting from my overall appreciation of it. I can only assume its down to the processing, it feels as though its somehow lost its natural look. I''m pleased for you that most people here appreciated and enjoyed it, scoring well in a highly contested challenge, well done Janine, Sid', '2015-08-20 14:49:54.000000', NULL, 0),
(7398749, 1138565, 25024, '<td valign="top">*Hello from Sid and the Critique Club*<br/> <br/>A very appealing sunset assumed to meet the challenge.<br/> <br/>What a grab shot! In itself it is a very appealing shot of a lovely location in a good composition. I like both the left and right of the image and the position of the sun.<br/> <br/>Like your commenter I have a problem with the sudden transitions they feel unnatural to the overall detriment of the image. You would undoubtedly have had little detail in the shadows and to get it back it looks as though you have pushed the curves beyond normal limits. I am having problems reconciling the feint red trees I am seeing between the silhouetted trees on the right, this may be down to selection problems.<br/> <br/>Is that really the colour of the sky? You are in a part of the world I have never experienced and this may well be the case but those, like me, who haven''t seen skies of such intensity are bound to ask the same question and unfortunately it may well affect their reaction to it, lovely as it is.<br/> <br/>Thank you for submitting an appealing image, Sid</td>', '*Hello from Sid and the Critique Club* A very appealing sunset assumed to meet the challenge. What a grab shot! In itself it is a very appealing shot of a lovely location in a good composition. I like both the left and right of the image and the position of the sun. Like your commenter I have a problem with the sudden transitions they feel unnatural to the overall detriment of the image. You would undoubtedly have had little detail in the shadows and to get it back it looks as though you have pushed the curves beyond normal limits. I am having problems reconciling the feint red trees I am seeing between the silhouetted trees on the right, this may be down to selection problems. Is that really the colour of the sky? You are in a part of the world I have never experienced and this may well be the case but those, like me, who haven''t seen skies of such intensity are bound to ask the same question and unfortunately it may well affect their reaction to it, lovely as it is. Thank you for submitting an appealing image, Sid', '2015-08-20 15:07:32.000000', NULL, 0),
(7398943, 1139447, 25024, '<td valign="top">*Hello from Sid and the Critique Club*<br/> <br/>Congratulations on your top ten placing for your landscape that is assumed to meet the challenge.<br/> <br/>Your lens has really emphasised the rocky foreground so that the unique nature of the rocks becomes a major part of the image. I like your use of the puddle to reflect the buildings too, it works well. The suns rays are also a nice element that adds to the overall result.<br/> <br/>I know I am in a minority here but I am not keen on the HDR processing, I prefer a more natural looking exposure. I am pleased for you that it has been well received and has done so well especially given the competitive nature of the challenge, well done, Sid</td>', '*Hello from Sid and the Critique Club* Congratulations on your top ten placing for your landscape that is assumed to meet the challenge. Your lens has really emphasised the rocky foreground so that the unique nature of the rocks becomes a major part of the image. I like your use of the puddle to reflect the buildings too, it works well. The suns rays are also a nice element that adds to the overall result. I know I am in a minority here but I am not keen on the HDR processing, I prefer a more natural looking exposure. I am pleased for you that it has been well received and has done so well especially given the competitive nature of the challenge, well done, Sid', '2015-08-21 08:24:48.000000', NULL, 0),
(7398948, 1138616, 25024, '<td valign="top">*Hello from Sid and the Critique Club*<br/> <br/>A natural portrait, assumed to meet the challenge.<br/> <br/>Your portrait has a lot of appeal, in particular for the natural moment you have captured of the girl looking longly at the tempting goods on display. It also conveys a desire to be out of the cold environment and in the warmth of the shop. Her clenched hands add to this feeling too.<br/> <br/>Your exposure is on the plus side which also helps convey the whites and therefore the coldness of the scene and the falling snowflakes are the final essential ingredient that makes it all work well together. I like that we are able to see the girls reflection in the glass together with detail inside.<br/> <br/>The top right feels as though you have added a white gradient to the upper part of the image, you may well not have done but it does feel a little unnatural in comparison with the rest of the image, perhaps it is just the snowfall.<br/> <br/>Anyway, well done for such a high placing in this tough challenge a well deserved result, Sid</td>', '*Hello from Sid and the Critique Club* A natural portrait, assumed to meet the challenge. Your portrait has a lot of appeal, in particular for the natural moment you have captured of the girl looking longly at the tempting goods on display. It also conveys a desire to be out of the cold environment and in the warmth of the shop. Her clenched hands add to this feeling too. Your exposure is on the plus side which also helps convey the whites and therefore the coldness of the scene and the falling snowflakes are the final essential ingredient that makes it all work well together. I like that we are able to see the girls reflection in the glass together with detail inside. The top right feels as though you have added a white gradient to the upper part of the image, you may well not have done but it does feel a little unnatural in comparison with the rest of the image, perhaps it is just the snowfall. Anyway, well done for such a high placing in this tough challenge a well deserved result, Sid', '2015-08-21 08:45:03.000000', NULL, 0),
(7398951, 1138961, 25024, '<td valign="top">*Hello from Sid and the Critique Club*<br/> <br/>An amazing natural scene assumed to meet the challenge.<br/> <br/>What an enormous ice cave this is and our perception of it is hugely enhanced by the essential addition of the person to give it all a sense of scale, it then becomes something quite staggeringly phenomenal. If I hadn''t had the wonderful experience of Iceland and its amazing colours I would be bound to question that it really was this blue, but with the benefit of that experience I can easily imagine that this is how it really is.<br/> <br/>I am amazed at how much light there is in there, you have been able to stop the lens down for a larger DOF and at ISO 100 you are still only ½ a second. If you have used any artificial light then you''ve done a masterful job of it because it looks 100% natural to me, so well done if you have. It''s really quite captivating all the amazing folds and shapes and textures there are in the icy surroundings, I hope to see this or similar one day soon.<br/> <br/>Thank you for an amazing image Otto, Sid</td>', '*Hello from Sid and the Critique Club* An amazing natural scene assumed to meet the challenge. What an enormous ice cave this is and our perception of it is hugely enhanced by the essential addition of the person to give it all a sense of scale, it then becomes something quite staggeringly phenomenal. If I hadn''t had the wonderful experience of Iceland and its amazing colours I would be bound to question that it really was this blue, but with the benefit of that experience I can easily imagine that this is how it really is. I am amazed at how much light there is in there, you have been able to stop the lens down for a larger DOF and at ISO 100 you are still only ½ a second. If you have used any artificial light then you''ve done a masterful job of it because it looks 100% natural to me, so well done if you have. It''s really quite captivating all the amazing folds and shapes and textures there are in the icy surroundings, I hope to see this or similar one day soon. Thank you for an amazing image Otto, Sid', '2015-08-21 08:56:48.000000', NULL, 0),
(7398959, 1139375, 25024, '<td valign="top">*Hello from Sid and the Critique Club*<br/> <br/>A pleasing scene assumed to meet the challenge.<br/> <br/>This tranquil scene is all about the quality of light, the gentle rays leading us from bright sunlight to the inner portion of the scene and the illuminated hulls reflected in the water, the very things that obviously attracted you in the first place. It''s a shame the boat on the left is such an ugly beast.<br/> <br/>Apart from the gentler brighter light the scene is generally low key and fairly monotone, verging towards black and white with subtle colouring. The only parts of the image that break that quality are the American flag on the left and, this is where I have the only problem with the image, the person on the left. He is so extremely positioned right on the edge of the frame that he would be better cropped out. If your original has more scene to the left then he should be included as his presence definitely adds but not in this extreme position. If he were to be added with space around him then he also ought to be dodged to subdue his colouring more in keeping with the rest of the image.<br/> <br/>Thank you for an interesting submission, Sid</td>', '*Hello from Sid and the Critique Club* A pleasing scene assumed to meet the challenge. This tranquil scene is all about the quality of light, the gentle rays leading us from bright sunlight to the inner portion of the scene and the illuminated hulls reflected in the water, the very things that obviously attracted you in the first place. It''s a shame the boat on the left is such an ugly beast. Apart from the gentler brighter light the scene is generally low key and fairly monotone, verging towards black and white with subtle colouring. The only parts of the image that break that quality are the American flag on the left and, this is where I have the only problem with the image, the person on the left. He is so extremely positioned right on the edge of the frame that he would be better cropped out. If your original has more scene to the left then he should be included as his presence definitely adds but not in this extreme position. If he were to be added with space around him then he also ought to be dodged to subdue his colouring more in keeping with the rest of the image. Thank you for an interesting submission, Sid', '2015-08-21 09:31:01.000000', NULL, 0),
(7398996, 1139039, 25024, '<td valign="top">*Hello from Sid and the Critique Club*<br/> <br/>A portrait with a difference assumed to meet the challenge.<br/> <br/>I do like an original approach to any photography and this fits the bill in that respect. I like the hat, the exposure is good and your choice of aperture has enabled detail in the facial features as well as the goggles. As a straightforward portrait in natural light it does the job.<br/> <br/>This, I''m afraid, is where I part company with your commenters, because I do not like the goggles and as they are such an integral part of the image unfortunately it does not work for me. In most portraits the most important element are the eyes, as they say, the soul is held there so the fact that we cannot see his eyes at all means it does not work for me at all. Perhaps I am completely missing the point, if it is intended as a fun image I wish it were a little more obvious. Given your additional information about the sandstorm I doubt it is intended as a fun image the sand on his face confirms that but how many of your viewers would have realised this is in doubt.<br/> <br/>Thanks for your submission, Sid</td>', '*Hello from Sid and the Critique Club* A portrait with a difference assumed to meet the challenge. I do like an original approach to any photography and this fits the bill in that respect. I like the hat, the exposure is good and your choice of aperture has enabled detail in the facial features as well as the goggles. As a straightforward portrait in natural light it does the job. This, I''m afraid, is where I part company with your commenters, because I do not like the goggles and as they are such an integral part of the image unfortunately it does not work for me. In most portraits the most important element are the eyes, as they say, the soul is held there so the fact that we cannot see his eyes at all means it does not work for me at all. Perhaps I am completely missing the point, if it is intended as a fun image I wish it were a little more obvious. Given your additional information about the sandstorm I doubt it is intended as a fun image the sand on his face confirms that but how many of your viewers would have realised this is in doubt. Thanks for your submission, Sid', '2015-08-21 10:51:45.000000', NULL, 0),
(7399002, 1138273, 25024, '<td valign="top">*Hello from Sid and the Critique Club*<br/> <br/>An interesting image presumed to meet the challenge.<br/> <br/>An interesting moment taken against a cold looking winter landscape. The composition fails in as much as the strong focal point of the paraglider is just far too central. I don''t know if you have cropped from a larger original but just taking what we have here I would suggest that a far stronger composition would be to move towards a more traditional aspect ratio with the figure in the top right flying in towards the rest of the image. You could remove all that white from the top and crop to just above him, I think it would make for a better result.<br/> <br/>Thank you for your submission, Sid</td>', '*Hello from Sid and the Critique Club* An interesting image presumed to meet the challenge. An interesting moment taken against a cold looking winter landscape. The composition fails in as much as the strong focal point of the paraglider is just far too central. I don''t know if you have cropped from a larger original but just taking what we have here I would suggest that a far stronger composition would be to move towards a more traditional aspect ratio with the figure in the top right flying in towards the rest of the image. You could remove all that white from the top and crop to just above him, I think it would make for a better result. Thank you for your submission, Sid', '2015-08-21 11:01:30.000000', NULL, 0),
(7419871, 1138631, 38032, '<td valign="top">I like what you have here. The composition is good and the subject is great. I gave it a 7.<br/>Criticism: The entire image is a bit soft and the color is off (maybe the white balance).  That may have hurt the score a bit.  When I have a chance,  I will try to play with a copy of it a little bit to see what you think.</td>', 'I like what you have here. The composition is good and the subject is great. I gave it a 7.Criticism: The entire image is a bit soft and the color is off (maybe the white balance).  That may have hurt the score a bit.  When I have a chance,  I will try to play with a copy of it a little bit to see what you think.', '2015-12-02 11:40:15.000000', NULL, 0),
(7419948, 1138631, 38032, '<td valign="top">I gave it a go. A slight change to the white balance (warmer), contrast, clarity, exposure and crop (this was all done in Adobe Lightroom).<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1171259" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/35000-39999/38032/120/Copyrighted_Image_Reuse_Prohibited_1171259.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/35000-39999/38032/120/Copyrighted_Image_Reuse_Prohibited_1171259.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/35000-39999/38032/120/Copyrighted_Image_Reuse_Prohibited_1171259.jpg"/></a> <br/>Processing can make a difference with a well-composed image like this. Your exposure was right on for something right of the camera - it just needs some life given to it in post-processing. You might be surprised at how much post processing there is on some images. <a href="//phlearn.com/" rel="nofollow" target="_blank">phlearn</a> is one good place to get some tips on post processing.<br/></td>', 'I gave it a go. A slight change to the white balance (warmer), contrast, clarity, exposure and crop (this was all done in Adobe Lightroom). Processing can make a difference with a well-composed image like this. Your exposure was right on for something right of the camera - it just needs some life given to it in post-processing. You might be surprised at how much post processing there is on some images. phlearn is one good place to get some tips on post processing.', '2015-12-02 14:48:53.000000', NULL, 0),
(7475114, 1138283, 68504, '<td valign="top">wow.</td>', 'wow.', '2016-09-22 02:01:53.000000', NULL, 0),
(7483017, 1139420, 86447, '<td valign="top">Were you vacationing on Long Island? Or do you live there?  <br/> <br/>This is a very cool shot.   A unique view that could be taken anywhere... but not by "anyone".  :D<br/> <br/>Well done.<br/></td>', 'Were you vacationing on Long Island? Or do you live there?   This is a very cool shot.   A unique view that could be taken anywhere... but not by "anyone".  :D Well done.', '2016-11-17 19:58:23.000000', NULL, 0),
(7551699, 1138949, 68504, '<td valign="top">lovely light hues and graceful dancings here and there.</td>', 'lovely light hues and graceful dancings here and there.', '2018-01-09 01:56:25.000000', NULL, 0),
(7585267, 1138735, 67258, '<td valign="top">This really is very lovely - and I see from the date that your little birthday girl will soon be 6!</td>', 'This really is very lovely - and I see from the date that your little birthday girl will soon be 6!', '2018-07-24 04:48:39.000000', NULL, 0),
